(function() {
    'use strict';

    class PowerShiftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'PowerShift: Change Management';
            this.version = '1.1.0';

            this.ROUNDS = [
                { title_key: 'round1_title', brief_key: 'round1_brief', inputPanel: 'round1Inputs' },
                { title_key: 'round2_title', brief_key: 'round2_brief', inputPanel: 'round2Inputs' },
                { title_key: 'round3_title', brief_key: 'round3_brief', inputPanel: 'round3Inputs' },
                { title_key: 'round4_title', brief_key: 'round4_brief', inputPanel: 'round4Inputs' },
                { title_key: 'round5_title', brief_key: 'round5_brief', inputPanel: 'round5Inputs' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coalitionStrength: 20,
                    transformationMomentum: 25,
                    organizationalTrust: 30,
                    budget: 500000000,
                    carlosRelationship: -40,
                    patriciaAlignment: 30,
                    miguelEngagement: 50,
                    anaSupport: 60,
                    employeeMorale: 35,
                    quickWinScore: 0,
                    institutionalizationScore: 0,
                    coalitionHistory: [],
                    momentumHistory: [],
                    trustHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    coalitionStrategy: 'broad',
                    carlosApproach: 'coopt',
                    patriciaEngagement: 'empower_ecommerce',
                    miguelEmpowerment: 'full'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            var period = st.currentPeriod || 1;

            if (period === 1) {
                var cs = document.getElementById('coalitionStrategyInput');
                var ca = document.getElementById('carlosApproachInput');
                var pe = document.getElementById('patriciaEngagementInput');
                var me = document.getElementById('miguelEmpowermentInput');
                if (cs) decisions.coalitionStrategy = cs.value;
                if (ca) decisions.carlosApproach = ca.value;
                if (pe) decisions.patriciaEngagement = pe.value;
                if (me) decisions.miguelEmpowerment = me.value;
            } else if (period === 2) {
                var ua = document.getElementById('urgencyApproachInput');
                var cc = document.getElementById('commChannelInput');
                var tr = document.getElementById('transparencyInput');
                var ms = document.getElementById('messagingInput');
                if (ua) decisions.urgencyApproach = ua.value;
                if (cc) decisions.commChannel = cc.value;
                if (tr) decisions.transparencyLevel = tr.value;
                if (ms) decisions.messagingStyle = ms.value;
            } else if (period === 3) {
                var q1 = document.getElementById('quickWin1Input');
                var q2 = document.getElementById('quickWin2Input');
                var wg = document.getElementById('winGovernanceInput');
                var ex = document.getElementById('expectationInput');
                if (q1) decisions.quickWin1 = q1.value;
                if (q2) decisions.quickWin2 = q2.value;
                if (wg) decisions.winGovernance = wg.value;
                if (ex) decisions.expectationMgmt = ex.value;
                if (decisions.quickWin1 === decisions.quickWin2) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('same_win_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var cr = document.getElementById('crisisResponseInput');
                var co = document.getElementById('coalitionCommInput');
                var ci = document.getElementById('ceoInvolvementInput');
                var cn = document.getElementById('contingencyInput');
                if (cr) decisions.crisisResponse = cr.value;
                if (co) decisions.coalitionComm = co.value;
                if (ci) decisions.ceoInvolvement = ci.value;
                if (cn) decisions.contingency = cn.value;
            } else if (period === 5) {
                var ef = document.getElementById('embeddingFocusInput');
                var ct = document.getElementById('ctoTransitionInput');
                var ts = document.getElementById('talentStrategyInput');
                var gv = document.getElementById('governanceInput');
                if (ef) decisions.embeddingFocus = ef.value;
                if (ct) decisions.ctoTransition = ct.value;
                if (ts) decisions.talentStrategy = ts.value;
                if (gv) decisions.governanceModel = gv.value;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var dCoalition = 0;
            var dMomentum = 0;
            var dTrust = 0;
            var dBudget = 0;
            var dCarlos = 0;
            var dPatricia = 0;
            var dMiguel = 0;
            var dAna = 0;
            var dMorale = 0;
            var dQuickWin = 0;
            var dInstitutionalization = 0;

            if (period === 1) {
                if (d.coalitionStrategy === 'broad') { dCoalition += 15; dTrust += 5; }
                else if (d.coalitionStrategy === 'targeted') { dCoalition += 10; dTrust += 2; }
                else if (d.coalitionStrategy === 'top_down') { dCoalition += 5; dTrust -= 10; dMomentum += 5; }

                if (d.carlosApproach === 'coopt') { dCarlos += 15; dTrust += 5; dCoalition += 3; }
                else if (d.carlosApproach === 'circumvent') { dCoalition += 5; dCarlos -= 5; }
                else if (d.carlosApproach === 'confront') {
                    if (ds.carlosRelationship < -30) { dCarlos -= 20; dMomentum += 5; }
                    else { dCarlos -= 10; dTrust -= 5; dCoalition -= 5; }
                }

                if (d.patriciaEngagement === 'empower_ecommerce') { dPatricia += 20; dCoalition += 5; dMomentum += 3; }
                else if (d.patriciaEngagement === 'assure_role') { dPatricia += 10; dCoalition += 2; }

                if (d.miguelEmpowerment === 'full') { dMiguel += 25; dCoalition += 10; dMomentum += 5; }
                else if (d.miguelEmpowerment === 'moderate') { dMiguel += 15; dCoalition += 5; }
                else { dMiguel += 5; }

                dAna += 5;
                dBudget = -20000000;
                dMorale += 3;
            }

            else if (period === 2) {
                if (d.urgencyApproach === 'blended') { dMomentum += 15; dTrust += 3; }
                else if (d.urgencyApproach === 'data_driven') { dMomentum += 10; dTrust += 2; }
                else if (d.urgencyApproach === 'vision_based') { dMomentum += 8; dMorale += 3; }
                else if (d.urgencyApproach === 'crisis_based') { dMomentum += 5; dTrust -= 5; dMorale -= 3; }

                if (d.commChannel === 'multi_channel') { dMomentum += 10; dTrust += 5; dCoalition += 3; }
                else if (d.commChannel === 'dialogues') { dTrust += 8; dMomentum += 3; }
                else if (d.commChannel === 'peer_networks') { dTrust += 7; dCoalition += 4; }
                else if (d.commChannel === 'townhalls') { dMomentum += 5; dTrust += 2; }

                if (d.transparencyLevel === 'qualified') { dTrust += 10; dMorale += 5; }
                else if (d.transparencyLevel === 'full') { dTrust += 15; dMorale -= 10; }
                else if (d.transparencyLevel === 'optimistic') { dTrust -= 5; dMorale += 5; }

                if (d.messagingStyle === 'customized') { dMomentum += 10; dPatricia += 5; dCarlos += 3; dAna += 5; }
                else { dMomentum += 3; }

                dBudget = -15000000;
                dMiguel += 3;
            }

            else if (period === 3) {
                var winScores = {
                    ecommerce_mvp: { momentum: 25, trust: 5, risk: 0.3, cost: 60000000, patricia: 15 },
                    mobile_sales: { momentum: 15, trust: 5, risk: 0.1, cost: 20000000, patricia: 0 },
                    cloud_finance: { momentum: 10, trust: 8, risk: 0.15, cost: 25000000, patricia: 0 },
                    analytics_dashboard: { momentum: 12, trust: 8, risk: 0.1, cost: 15000000, patricia: 3 },
                    customer_feedback: { momentum: 10, trust: 10, risk: 0.05, cost: 5000000, patricia: 2 }
                };

                var w1 = winScores[d.quickWin1] || winScores.analytics_dashboard;
                var w2 = winScores[d.quickWin2] || winScores.customer_feedback;

                var riskMod = 1.0;
                if (d.expectationMgmt === 'underpromise') { riskMod = 0.5; dTrust += 5; }
                else if (d.expectationMgmt === 'ambitious') { riskMod = 1.5; dTrust -= 5; }

                var fail1 = Math.random() < (w1.risk * riskMod);
                var fail2 = Math.random() < (w2.risk * riskMod);

                if (!fail1) {
                    dMomentum += w1.momentum;
                    dTrust += w1.trust;
                    dPatricia += w1.patricia;
                    dQuickWin += 30;
                } else {
                    dMomentum -= 5;
                    dTrust -= 8;
                    dQuickWin += 5;
                }

                if (!fail2) {
                    dMomentum += w2.momentum;
                    dTrust += w2.trust;
                    dPatricia += w2.patricia;
                    dQuickWin += 20;
                } else {
                    dMomentum -= 3;
                    dTrust -= 5;
                    dQuickWin += 3;
                }

                if (d.winGovernance === 'sponsor_aligned') { dCoalition += 10; dMomentum += 3; }
                else if (d.winGovernance === 'centralized') { dCoalition += 3; }
                else { dCoalition += 2; dTrust -= 2; }

                dBudget = -(w1.cost + w2.cost);
                dMorale += 5;
                dAna += 5;
                dMiguel += 5;
            }

            else if (period === 4) {
                if (d.crisisResponse === 'coopt_redirect') {
                    dCarlos += 30;
                    dCoalition += 10;
                    dMomentum += 5;
                    dTrust += 8;
                    dMorale += 5;
                } else if (d.crisisResponse === 'circumvent_isolate') {
                    dCoalition += 5;
                    dCarlos -= 15;
                    dMomentum += 3;
                    dMorale += 2;
                } else if (d.crisisResponse === 'confront_contain') {
                    if (ds.carlosRelationship > 0) {
                        dCarlos -= 30;
                        dTrust -= 10;
                        dCoalition -= 5;
                        dMorale -= 8;
                    } else {
                        dCarlos -= 20;
                        dMomentum += 8;
                        dCoalition += 3;
                    }
                }

                if (d.coalitionComm === 'transparent') { dTrust += 10; dCoalition += 5; }
                else if (d.coalitionComm === 'controlled') { dTrust += 3; dCoalition += 2; }
                else { dTrust -= 5; dCoalition -= 3; }

                if (d.ceoInvolvement === 'active') { dCoalition += 15; dMomentum += 10; dTrust += 5; }
                else if (d.ceoInvolvement === 'moderate_ceo') { dCoalition += 5; dMomentum += 3; }
                else { dMomentum -= 3; }

                if (d.contingency === 'succession_ready') { dCoalition += 5; dTrust += 3; }
                else if (d.contingency === 'negotiation') { dCarlos += 5; dTrust += 2; }
                else { dTrust -= 2; }

                dBudget = -10000000;
                dPatricia += 5;
                dAna += 3;
                dMiguel += 3;
            }

            else if (period === 5) {
                if (d.embeddingFocus === 'comprehensive') { dInstitutionalization += 25; dTrust += 5; dMomentum += 5; }
                else if (d.embeddingFocus === 'systems') { dInstitutionalization += 10; dMomentum += 3; }
                else if (d.embeddingFocus === 'incentives') { dInstitutionalization += 10; dMorale += 5; }
                else if (d.embeddingFocus === 'culture') { dInstitutionalization += 10; dTrust += 5; }

                if (d.ctoTransition === 'operational_role') { dInstitutionalization += 15; dTrust += 10; dCoalition += 5; }
                else if (d.ctoTransition === 'cdo_role') { dInstitutionalization += 10; dMomentum += 5; }
                else if (d.ctoTransition === 'advisory') { dInstitutionalization += 8; dTrust += 3; }
                else { dTrust -= 5; }

                if (d.talentStrategy === 'balanced') { dInstitutionalization += 15; dMorale += 10; dMomentum += 5; }
                else if (d.talentStrategy === 'hire_digital') { dInstitutionalization += 10; dMorale -= 5; dMomentum += 8; }
                else if (d.talentStrategy === 'reskill') { dInstitutionalization += 8; dMorale += 10; }

                if (d.governanceModel === 'quarterly_review') { dInstitutionalization += 10; dTrust += 3; }
                else if (d.governanceModel === 'embedded') { dInstitutionalization += 8; dMomentum += 3; }
                else { dInstitutionalization += 3; }

                dBudget = -30000000;
                dCarlos += 3;
                dPatricia += 3;
                dAna += 3;
                dMiguel += 3;
            }

            var clamp = function(val, lo, hi) { return Math.max(lo, Math.min(hi, val)); };

            ds.coalitionStrength = clamp(ds.coalitionStrength + dCoalition, 0, 100);
            ds.transformationMomentum = clamp(ds.transformationMomentum + dMomentum, 0, 100);
            ds.organizationalTrust = clamp(ds.organizationalTrust + dTrust, 0, 100);
            ds.budget = Math.max(0, ds.budget + dBudget);
            ds.carlosRelationship = clamp(ds.carlosRelationship + dCarlos, -100, 100);
            ds.patriciaAlignment = clamp(ds.patriciaAlignment + dPatricia, 0, 100);
            ds.miguelEngagement = clamp(ds.miguelEngagement + dMiguel, 0, 100);
            ds.anaSupport = clamp(ds.anaSupport + dAna, 0, 100);
            ds.employeeMorale = clamp(ds.employeeMorale + dMorale, 0, 100);
            ds.quickWinScore = clamp(ds.quickWinScore + dQuickWin, 0, 100);
            ds.institutionalizationScore = clamp(ds.institutionalizationScore + dInstitutionalization, 0, 100);

            ds.coalitionHistory.push(ds.coalitionStrength);
            ds.momentumHistory.push(ds.transformationMomentum);
            ds.trustHistory.push(ds.organizationalTrust);
            var _tot = ds.coalitionStrength + ds.transformationMomentum + ds.organizationalTrust + ds.quickWinScore + ds.institutionalizationScore;
            ds.score = Math.max(0, Math.min(100, Math.round(_tot / 5)));
            ds.performance = { overallScore: ds.score, rating: (_tot > 350 ? 'Excellent: Transformation Leader' : _tot > 250 ? 'Good: Effective Change Agent' : _tot > 150 ? 'Needs Improvement: Struggling Transformation' : 'Failed Transformation'), rawScore: _tot };

            this._updateStakeholderBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                coalitionStrength: ds.coalitionStrength,
                transformationMomentum: ds.transformationMomentum,
                organizationalTrust: ds.organizationalTrust,
                budget: ds.budget,
                carlosRelationship: ds.carlosRelationship,
                patriciaAlignment: ds.patriciaAlignment,
                miguelEngagement: ds.miguelEngagement,
                anaSupport: ds.anaSupport,
                employeeMorale: ds.employeeMorale,
                quickWinScore: ds.quickWinScore,
                institutionalizationScore: ds.institutionalizationScore,
                dCoalition: dCoalition,
                dMomentum: dMomentum,
                dTrust: dTrust
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('coalitionDisplay', 'domainState.coalitionStrength',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('momentumDisplay', 'domainState.transformationMomentum',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('trustDisplay', 'domainState.organizationalTrust',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('budgetDisplay', 'domainState.budget',
                function(v) { return '$' + Math.round(v / 1000000) + 'M'; });
            uiManager.bind('carlosDisplay', 'domainState.carlosRelationship',
                function(v) { return Math.round(v); });
            uiManager.bind('patriciaDisplay', 'domainState.patriciaAlignment',
                function(v) { return Math.round(v); });
            uiManager.bind('miguelDisplay', 'domainState.miguelEngagement',
                function(v) { return Math.round(v); });
            uiManager.bind('anaDisplay', 'domainState.anaSupport',
                function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                progressChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Coalition Strength',
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Momentum',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Trust',
                                data: [],
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Transformation Progress' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                },
                stakeholderChart: {
                    type: 'bar',
