        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var total = (r.coalitionStrength || 0) + (r.transformationMomentum || 0) + (r.organizationalTrust || 0) + (r.quickWinScore || 0) + (r.institutionalizationScore || 0);
            var performance = 'Failed Transformation';
            var insights = [];

            if (total > 350) {
                performance = 'Excellent: Transformation Leader';
                insights.push('Outstanding coalition building and change institutionalization.');
            } else if (total > 250) {
                performance = 'Good: Effective Change Agent';
                insights.push('Solid progress on most fronts. Consider strengthening weaker areas.');
            } else if (total > 150) {
                performance = 'Needs Improvement: Struggling Transformation';
                insights.push('The transformation faces significant headwinds. Review stakeholder strategy.');
            } else {
                insights.push('The transformation has largely failed. Resistance was not adequately managed.');
            }

            if (r.carlosRelationship > 20) insights.push('Carlos was successfully brought into the coalition.');
            else if (r.carlosRelationship < -30) insights.push('Carlos remains a strong opponent. The manufacturing division may resist long-term.');

            if (r.institutionalizationScore > 50) insights.push('Change has been well embedded into systems and culture.');
            else insights.push('Institutionalization is weak. The transformation may revert when leadership attention shifts.');

            var overallScore = Math.max(0, Math.min(100, Math.round(total / 5)));
            return {
                overallScore: overallScore,
                score: overallScore,
                totalScore: total,
                performance: performance,
                coalitionStrength: r.coalitionStrength,
                momentum: r.transformationMomentum,
                trust: r.organizationalTrust,
                quickWins: r.quickWinScore,
                institutionalization: r.institutionalizationScore,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.coalitionStrength < 30 && state.currentPeriod <= 3) {
                return window.mySimulation.t('hint_weak_coalition');
            }
            if (ds.carlosRelationship < -50 && state.currentPeriod === 3) {
                return window.mySimulation.t('hint_carlos_danger');
            }
            if (ds.transformationMomentum < 30 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_low_momentum');
            }
            if (ds.organizationalTrust < 25) {
                return window.mySimulation.t('hint_low_trust');
            }
            if (results.dCoalition > 15) {
                return window.mySimulation.t('hint_great_coalition');
            }
            if (ds.budget < 100000000 && state.currentPeriod < 5) {
                return window.mySimulation.t('hint_budget_low');
            }
            return null;
        }

