        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var briefText = window.mySimulation ? window.mySimulation.t(round.brief_key) : '';
                briefEl.innerHTML = briefText;
            }

            var panels = ['round1Inputs', 'round2Inputs', 'round3Inputs', 'round4Inputs', 'round5Inputs'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) {
                    panel.style.display = (panels[i] === round.inputPanel) ? '' : 'none';
                }
            }

            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                this._updateStakeholderBars(window.mySimulation.state.domainState);
            }
        }

        _updateStakeholderBars(ds) {
            var carlosBar = document.getElementById('carlosBar');
            if (carlosBar) {
                var carlosVal = ds.carlosRelationship;
                var carlosWidth = Math.abs(carlosVal);
                carlosBar.style.width = carlosWidth + '%';
                if (carlosVal >= 0) {
                    carlosBar.className = 'powershift-sim-bar-fill';
                } else {
                    carlosBar.className = 'powershift-sim-bar-fill powershift-sim-bar-negative';
                }
            }
            var patriciaBar = document.getElementById('patriciaBar');
            if (patriciaBar) {
                patriciaBar.style.width = ds.patriciaAlignment + '%';
                patriciaBar.className = ds.patriciaAlignment >= 50 ? 'powershift-sim-bar-fill' : 'powershift-sim-bar-fill powershift-sim-bar-negative';
            }
            var miguelBar = document.getElementById('miguelBar');
            if (miguelBar) {
                miguelBar.style.width = ds.miguelEngagement + '%';
                miguelBar.className = 'powershift-sim-bar-fill';
            }
            var anaBar = document.getElementById('anaBar');
            if (anaBar) {
                anaBar.style.width = ds.anaSupport + '%';
                anaBar.className = 'powershift-sim-bar-fill';
